<?php require '_init.php';$pageTitle='Customers';if(post()){verify_csrf();query('UPDATE users SET is_active=1-is_active WHERE id=?',[number('id')]);flash('Customer account updated.');redirect('admin/customers.php');}$id=number('id',true);require '../includes/header.php';?><section class="container section"><h1>Customers</h1><div class="table-wrap"><table><thead><tr><th>Username</th><th>Email</th><th>Joined</th><th>Account</th><th>Orders</th></tr></thead><tbody><?php foreach(query('SELECT id,username,email,created_at,is_active FROM users ORDER BY id DESC')->fetchAll() as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e($u['created_at'])?></td><td><form method="post"><?php csrf();?><input type="hidden" name="id" value="<?=$u['id']?>"><button class="outline"><?=$u['is_active']?'Disable':'Enable'?> account</button></form></td><td><a href="<?=e(url('admin/customers.php?id='.$u['id']))?>">Order history</a></td></tr><?php endforeach;?></tbody></table></div><?php if($id):?><h2>Customer #<?=$id?> order history</h2><?php $orders=query('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$id])->fetchAll();if(!$orders)echo '<p>No orders yet.</p>';foreach($orders as $o):?><div class="panel"><a href="<?=e(url('admin/orders.php?id='.$o['id']))?>">Order #<?=$o['id']?></a> · <?=money($o['total'])?> · <?=e($o['status'])?></div><?php endforeach;endif;?></section><?php require '../includes/footer.php';?>
